SELECT COUNT(*) FROM (
    SELECT d.recordregistry 
    FROM dataflow d
    JOIN dataprofile dp ON d.recordregistry = dp.flowsign
    JOIN riskmanagement rm ON d.recordregistry = rm.flowlink
) sub;

SELECT COUNT(*) FROM (
    SELECT d.recordregistry 
    FROM dataflow d
    JOIN dataprofile dp ON d.recordregistry = dp.flowsign
    JOIN riskmanagement rm ON d.recordregistry = rm.flowlink
) a;

SELECT COUNT(*) FROM (
    SELECT d.recordregistry 
    FROM dataflow d
    JOIN dataprofile dp ON d.recordregistry = dp.flowsign
    JOIN riskmanagement rm ON dp.riskjoin = rm.risktrace
) b;
